entries[138972] = { ["name"] = "Eingemachte Bilbeeren", ["text"] = "Benutzen: Solange sie noch nicht verdorben ist, stellt diese Nahrung im Verlauf von 20 Sek. 38462 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Dieser Behälter enthält ein Beerenmus, bedeckt von einer grünen 'Schutzschicht'.\"\nVerkaufspreis:" }
entries[138973] = { ["name"] = "Beißend riechender Schimmelgamalost", ["text"] = "Benutzen: Solange sie noch nicht verdorben ist, stellt diese Nahrung im Verlauf von 20 Sek. 38462 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Allgemein wird angenommen, dass die grünen Bestandteile dem Schutz dienen. Ihr solltet diese Teile auf keinen Fall essen.\"\nVerkaufspreis:" }
entries[138974] = { ["name"] = "Verbrutzeltes Urhorn", ["text"] = "Benutzen: Solange sie noch nicht verdorben ist, stellt diese Nahrung im Verlauf von 20 Sek. 38462 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Bis zur Unkenntlichkeit verbrannt, damit niemand daran erinnert wird, was das einmal war.\"\nVerkaufspreis:" }
entries[138975] = { ["name"] = "Gletscherwasser vom Hochberg", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Es war makellos am Tag, als es eingesammelt wurde, obwohl seit jenem Tag wohl schon einige Zeit vergangen ist...\"\nVerkaufspreis:" }
