entries[139312] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Hexenmeister\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
