entries[139316] = { ["name"] = "Verschimmelter Pergamentfetzen", ["text"] = "\"Einfach nur ein Fetzen verschimmeltes Pergament. Welche wundersame Geschichte wohl einst darauf geschrieben stand?\"\nVerkaufspreis:" }
entries[139317] = { ["name"] = "Zerbrochene uralte Waffe", ["text"] = "\"Diese Waffe ist verrostet und zerbrochen.\"\nVerkaufspreis:" }
entries[139318] = { ["name"] = "Zerrissenes Stoffstück", ["text"] = "\"Zu was dieses Stoffstück einst gehörte, vermag heute niemand mehr zu sagen.\"\nVerkaufspreis:" }
entries[139319] = { ["name"] = "Das Rabenauge", ["text"] = "Questgegenstand\nEinzigartig\n\"Die makellose Perfektion dieses Juwels wird nur noch von seinem potenziellen Nutzen für die Ungekrönten übertroffen.\"" }
entries[139320] = { ["name"] = "Verheerte Samenkapsel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Kontaminiert für 10 Sek. den Boden unter Euren Füßen, der Gegnern im Effektbereich pro Sekunde 63 Schattenschaden zufügt. Während Ihr Euch in diesem Bereich aufhaltet, erhaltet Ihr 9 Lebensraub. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[139321] = { ["name"] = "Schwärmender Pestbau", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Eure Schadenszauber haben eine Chance, einen Aasschwarm herbeizurufen, der Euer Ziel einhüllt und ihm im Verlauf von 10 Sek. 68 Naturschaden zufügt.\nVerkaufspreis:" }
entries[139322] = { ["name"] = "Kokon der erzwungenen Einsamkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nBenutzen: Hüllt Euch selbst in einen Kokon, wodurch Ihr für 10 Sek. in einen traumlosen Schlaf verfallt. Während dieser Zeit stellt Ihr 51 Mana pro Sekunde wieder her. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[139323] = { ["name"] = "Wirbelnder Wind", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, für 10 Sek. einen quälenden Zyklon an der Position des Ziels zu erzeugen, der pro Sekunde 5 Schattenschaden verursacht.\nVerkaufspreis:" }
entries[139324] = { ["name"] = "Becher mit Alptraumsekret", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass in der Nähe ein Alptraumsekret erschaffen wird. Das Absorbieren dieses Sekrets erhöht Eure Vielseitigkeit für 10 Sek. um 19 .\nVerkaufspreis:" }
entries[139325] = { ["name"] = "Spontane Gliedmaßen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Nahkampfangriffe haben eine Chance, für 12 Sek. Tentakel zu erzeugen, die Gegner in der Nähe angreifen und ihnen alle 0.75 Sek. 10 körperlichen Schaden zufügen.\nVerkaufspreis:" }
entries[139326] = { ["name"] = "Zuckende Sehne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nBenutzen: Erhaltet 10 Aufladungen 'Unerträgliches Flüstern'. Eure Schadenszauber übertragen für 30 Sek. je eine Aufladung 'Unerträgliches Flüstern' auf das Ziel. Dieser Effekt kann nur ein Mal alle 0.5 Sek. auftreten. Wenn alle Aufladungen übertragen wurden, verursacht jede von ihnen 22 Schattenschaden. (500ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[139327] = { ["name"] = "Ungezügelte Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nBenutzen: Erhöht Eure maximale Gesundheit um 182 und Eure Rüstung um 1 . Hält 30 Sek. lang an. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[139328] = { ["name"] = "Ursocs reißende Pranke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\nAnlegen: Eure kritischen automatischen Angriffe gewähren eine Chance, dass das Ziel im Verlauf von 8 Sek. 15 körperlichen Blutungsschaden erleidet.\nVerkaufspreis:" }
entries[139329] = { ["name"] = "Blutrünstiger Instinkt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\nAnlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, 10 Sek. lang Euer Tempo um 21 zu erhöhen. Dieser Effekt tritt häufiger im Kampf gegen Ziele mit niedriger Gesundheit auf.\nVerkaufspreis:" }
entries[139330] = { ["name"] = "Geschärfte Sinne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Eure Heilzauber haben eine Chance, Euer Tempo um 9 und Eure Intelligenz um 13 zu erhöhen. Hält 12 Sek. lang an.\nVerkaufspreis:" }
entries[139332] = { ["name"] = "Geschwärzte Portalsteinhalskette", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Tempowertung um + 5.\nVerkaufspreis:" }
entries[139333] = { ["name"] = "Horn des Cenarius", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Beschwört einen Irrwisch, um einen Verbündeten zu unterstützen. Wenn der Irrwisch die Position Eures Ziels erreicht, detoniert er und ruft innerhalb von 8 Metern 33 Heilung hervor. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[139334] = { ["name"] = "Der Ruf der Natur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nAnlegen: Eure Nahkampfangriffe haben eine Chance, Euch für 10 Sek. einen Segen eines der Verbündeten der Natur zu gewähren.\nVerkaufspreis:" }
entries[139335] = { ["name"] = "Groteske Statue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Gewährt eine Chance, dass die Seelen von Gegnern, die Euch angreifen, verdunkelt werden und sie Euch 20 Sek. lang (- 0 )% weniger Schaden zufügen. Weitere Anwendungen erhöhen die Effektivität von 'Verdunkelnde Seele', setzen jedoch nicht die Effektdauer zurück.\nVerkaufspreis:" }
entries[139336] = { ["name"] = "Zweig der Verderbnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, das Ziel für 20 Sek. mit 'Alptraumverderbnis' zu infizieren, durch die Eure Zauber bis zu 2 zusätzlichen Schaden als Schattenschaden verursachen. Alle 2 Sek. versucht 'Alptraumverderbnis', sich auf einen Gegner in der Nähe auszubreiten. Wenn sich keine nicht infizierten Gegner in der Nähe befinden, steigt die Intensität der Verderbnis an. (20s Abklingzeit)\nVerkaufspreis:" }
entries[139337] = { ["name"] = "Winterhauchwegwerfkleidung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stellt eine Kleidertruhe auf, damit Eure Schlachtzugs- oder Gruppenmitglieder etwas anprobieren können.\nWährend des Winterhauchfests ist die Abklingzeit verringert. (2 Std. Abklingzeit)\n\"Für die fröhliche Feststimmung an jedem Tag des Jahres!\"" }
entries[139338] = { ["name"] = "Glyphe 'Knisternder Kranichblitz'", ["text"] = "Klassen: Mönch\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eures Zaubers 'Knisternder Jadeblitz' hat nun die Farbe des Roten Kranichs. Exklusiv mit: Glyphe 'Knisternder Tigerblitz'\nVerkaufspreis:" }
entries[139339] = { ["name"] = "Glyphe 'Yu'lons Anmut'", ["text"] = "Klassen: Mönch\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert die Farbe der Kugeln Eurer 'Gabe des Ochsen' in das Grün von Yu'lon.\nVerkaufspreis:" }
