entries[139386] = { ["name"] = "Essenz des reinen Geistes", ["text"] = "Questgegenstand" }
entries[139387] = { ["name"] = "Schienbeinschützer des ertrunkenen Champions", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n10 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[139388] = { ["name"] = "Kodex der Befehlsgewalt", ["text"] = "Questgegenstand\n\"In diese Metallkugel sind Tausende winzige Teufelsrunen eingraviert, in denen Einzelheiten über den Angriff der Legion auf die Verheerten Inseln beschrieben werden.\"" }
entries[139389] = { ["name"] = "Verkohltes Medaillon", ["text"] = "\"Die Inschrift im Innern ist absolut unleserlich.\"\nVerkaufspreis:" }
entries[139390] = { ["name"] = "Artefaktforschungsnotizen", ["text"] = "Wird beim Aufheben gebunden\n\"Nachdem die Orden ihre Ressourcen untereinander teilten, wurden diese Bände gesammelten Wissens hinfällig.\"\nVerkaufspreis:" }
entries[139391] = { ["name"] = "Alainas Häubchen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[139392] = { ["name"] = "Schienbeinschützer der zehntausend Glieder", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n10 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[139393] = { ["name"] = "Knisternde Vliesgamaschen", ["text"] = "Wird beim Aufheben gebunden\nBeine Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[139394] = { ["name"] = "Fallschirmhose", ["text"] = "Wird beim Aufheben gebunden\nBeine Leder\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[139395] = { ["name"] = "Reverbiumdurchsetzte Beinplatten", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n15 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[139396] = { ["name"] = "Reverbiumkiesel", ["text"] = "\"Ein neues Mineral, das so gut wie unzerstörbar ist! Hätten wir doch nur genug, um etwas daraus herzustellen... vielleicht einen Schild...\"\nVerkaufspreis:" }
entries[139397] = { ["name"] = "Überflüssiger Ballast", ["text"] = "\"Unglaublich massiv, extrem schwer und aus irgendeinem Grund auch ziemlich übelriechend.\"\nVerkaufspreis:" }
entries[139398] = { ["name"] = "Hosenlaib", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 7500 / 5 * 20) Gesundheit und ( 3750 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Ausgebreitet sieht das gute Stück wie eine Hose aus. Und falls es mit der Alchemie nicht klappt...\"\nVerkaufspreis:" }
entries[139399] = { ["name"] = "Gallertartiger Klumpen", ["text"] = "\"Metallstücke, Fellfetzen und Zähne wabern in dem Glibber umher.\"\nVerkaufspreis:" }
entries[139400] = { ["name"] = "Von uralter Magie und ihrer Anwendung, ohne die Welt zu zerstören", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Sammlung des Wissens vieler großer Erzmagier der Kirin Tor. Enthält genaue Beschreibungen der Torheiten, die fahrlässige Magier vergangener Zeiten begangen haben.\"" }
entries[139401] = { ["name"] = "Das Schicksal von Aegwynn", ["text"] = "Questgegenstand\nEinzigartig\n\"Der letzte Teil der Aufzeichnungen über den Lebenswandel von Erzmagierin Aegwynn, Wächterin von Tirisfal. Verfasst vom Historiker Llore.\"" }
entries[139402] = { ["name"] = "Der Teufelsfoliant von Vorgalus Dor", ["text"] = "Questgegenstand\nEinzigartig\n\"Dämonische Aufzeichnungen des verstorbenen Hexenmeisters Vorgalus Dor, die Berichte über viele uralte und mächtige Waffen aus fernen Welten der Legion enthalten.\"" }
entries[139403] = { ["name"] = "Mächtige Magiefokusse und ihre Besitzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n\"Eine umfassende Auflistung historischer magischer Artefakte und Waffen, recherchiert und abgefasst von Erzmagier Karlain.\"" }
entries[139404] = { ["name"] = "Teufelsmotorzündung", ["text"] = "Questgegenstand\nEinzigartig\n\"Kling ziemlich wichtig. Hoffentlich weiß Jace, was damit zu tun ist.\"" }
