entries[139411] = { ["name"] = "Bankett der Schattenseite", ["text"] = "Benutzen: Platziert ein Bankett für Spielercharaktere in der Schattenseite.\n\nSpeist 25 Spielercharaktere.\nVerkaufspreis:" }
entries[139412] = { ["name"] = "Junge mutierte Kriegsschildkröten", ["text"] = "Benutzen: Platziert einige Haustiere auf dem Boden in der Nähe von Laura Malley, die Ihr und andere Spielercharaktere bekämpfen und fangen könnt.\n\nEnthält 4 Haustiere.\nVerkaufspreis:" }
entries[139416] = { ["name"] = "Aufgeblähter Kanalisationskarpfen", ["text"] = "\"Der hat so einiges zwischen die Kiemen bekommen...\"\n<Zum Öffnen rechtsklicken>" }
entries[139417] = { ["name"] = "Glyphe 'Fahle Flügel'", ["text"] = "Klassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Gleiten aktiv ist, habt Ihr nun gelbe Flügel. Exklusiv mit: Glyphe 'Teufelsschwingen' Glyphe 'Zerfledderte Flügel'\nVerkaufspreis:" }
entries[139418] = { ["name"] = "Totem des heilenden Flusses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Wählt einen Eurer Trupps aus, um 1 Vitalität wiederherzustellen." }
entries[139419] = { ["name"] = "Goldene Banane", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Wählt einen Eurer Champions aus, um ihm für eine Mission eine erhöhte Erfolgschance zu verleihen.\n\"Kann als Größenvergleich verwendet werden.\"" }
entries[139420] = { ["name"] = "Wildpilz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Wählt einen Eurer Trupps aus, um 1 Vitalität wiederherzustellen." }
entries[139421] = { ["name"] = "Rattenhengstharnisch", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig\nBenutzen: Beschwört eine Ratte, auf der Ihr in der Schattenseite reiten könnt und die Eure Bewegungsgeschwindigkeit um 100% erhöht." }
entries[139422] = { ["name"] = "Dämonischer Köder", ["text"] = "Benutzen: Setzt dies im Wasser von Dalarans Schattenseite ein, um Fische an die Oberfläche zu locken.\n\nDieser Effekt hält 5 Min. lang an.\nVerkaufspreis:" }
entries[139423] = { ["name"] = "Krokomojo", ["text"] = "Benutzen: Spült die Krokilisken aus den Kanalrohren in Dalarans Schattenseite.\n\nDieser Effekt hält 5 Min. lang an." }
entries[139424] = { ["name"] = "Kreischerpfeife", ["text"] = "Benutzen: Weckt die Fledermäuse in Dalarans Schattenseite auf.\n\nDieser Effekt hält 5 Min. lang an." }
entries[139425] = { ["name"] = "Wichtelbindender Vertrag", ["text"] = "Benutzen: Beschwört eine große Menge Wichtel in die Schattenseite.\nVerkaufspreis:" }
entries[139426] = { ["name"] = "Vertrag der Witwenschwester", ["text"] = "Benutzen: Ruft einige Schurkenanhänger der Witwe in die Schattenseite von Dalaran." }
entries[139427] = { ["name"] = "Zauberstab des wilden Manas", ["text"] = "Benutzen: Erhöht die Gesundheit und den Schaden eines der Bosse in Dalarans Schattenseite erheblich. Erhöht zusätzlich die Menge blinder Augen, die Ihr bei seinem Tod erbeutet.\n\nKann nicht auf Bosse angewandt werden, deren Gesundheit weniger als 90% beträgt." }
entries[139428] = { ["name"] = "Ein meisterhafter Plan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Wählt einen Eurer Champions aus, um ihm für eine Mission eine erhöhte Erfolgschance zu verleihen." }
entries[139431] = { ["name"] = "Kiste mit Rattenhengstharnischen", ["text"] = "Benutzen: Platziert eine Kiste mit Rattenhengstharnischen auf dem Boden, die Ihr und andere Spielercharaktere nutzen könnt, um in der Schattenseite aufsitzen zu können.\n\nEnthält 25 Reittiere.\nVerkaufspreis:" }
entries[139432] = { ["name"] = "Das Edikt des Feuers", ["text"] = "Questgegenstand\nEinzigartig\n\"Teil I des Kodex von Ra, der uralten Schrifttafeln der Weisheit.\"" }
entries[139433] = { ["name"] = "Das Edikt des Steins", ["text"] = "Questgegenstand\nEinzigartig\n\"Teil II des Kodex von Ra, der uralten Schrifttafeln der Weisheit.\"" }
entries[139434] = { ["name"] = "Das Edikt des Sturms", ["text"] = "Questgegenstand\nEinzigartig\n\"Teil III des Kodex von Ra, der uralten Schrifttafeln der Weisheit.\"" }
entries[139435] = { ["name"] = "Glyphe 'Teufelsschwingen'", ["text"] = "Klassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Gleiten aktiv ist, habt Ihr nun grüne Flügel. Exklusiv mit: Glyphe 'Fahle Flügel' Glyphe 'Zerfledderte Flügel'\nVerkaufspreis:" }
entries[139436] = { ["name"] = "Glyphe 'Zerfledderte Flügel'", ["text"] = "Klassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Gleiten aktiv ist, habt Ihr nun zerfledderte Flügel. Exklusiv mit: Glyphe 'Fahle Flügel' Glyphe 'Teufelsschwingen'\nVerkaufspreis:" }
entries[139437] = { ["name"] = "Glyphe 'Teufelsfeinde'", ["text"] = "Klassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Geistersicht' wird durch Teufelsenergie verändert, sodass Ihr alle Gegner in einem Teufelslicht seht.\nVerkaufspreis:" }
entries[139438] = { ["name"] = "Glyphe 'Schattenfeinde'", ["text"] = "Klassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Geistersicht' ist durch die Leere verdunkelt, sodass Ihr Gegner in Schatten gehüllt seht.\nVerkaufspreis:" }
entries[139439] = { ["name"] = "Schutz des hohen Hüters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n52 Rüstung\n+2 Stärke\n+7 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nVerkaufspreis:" }
entries[139442] = { ["name"] = "Glyphe 'Brandeilig'", ["text"] = "Klassen: Schurke\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Sprinten' hinterlässt eine Rauchfahne.\nVerkaufspreis:" }
entries[139445] = { ["name"] = "Teufelslexikon", ["text"] = "Questgegenstand\n\"Die schwarzen Seiten des Buches werden von einem schweren Metallverschluss zugehalten.\"" }
entries[139447] = { ["name"] = "Phiole des reinen Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Beschwört eine Lichtbrut, die für 10 Min. an Eurer Seite kämpft.\n\nDie Lichtbrut ist sehr ausdauernd und verspottet alle Gegner in der Nähe.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139448] = { ["name"] = "Phiole der dunklen Schatten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Beschwört einen Gesichtslosen, der für 10 Min. an Eurer Seite kämpft.\n\nDer Gesichtslose ist sehr ausdauernd und verspottet alle Gegner in der Nähe.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139449] = { ["name"] = "Essenz der Naaru", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Fokussiert das Licht der Naaru, um alle Gegner innerhalb von 15 Metern zwei Mal über einen Zeitraum von 4 Sek. mit (2000% der Zaubermacht) Heiligschaden zu verbrennen.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139450] = { ["name"] = "Sphäre der Leere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Ruft zwei Tentakel aus der Leere herbei, die auf alle Gegner innerhalb von 8 Metern vor Euch hinabschmettern und ihnen (2000% der Zaubermacht) Schattenschaden zufügen.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139451] = { ["name"] = "Wirbelnder Leerentrank", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Trinkt von dem dunklen Trank, um Euren Geist der Leere zu opfern.\n\nErzeugt im Verlauf der nächsten 10 Min. 10 Wahnsinn pro Sekunde.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139452] = { ["name"] = "Essenz des Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Entfesselt die Energie des Lichts, wodurch alle Gruppenmitglieder alle 2 Sek. um 5% ihrer maximalen Gesundheit geheilt werden.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139453] = { ["name"] = "Großer dämonischer Runenstein", ["text"] = "Questgegenstand\nEinzigartig" }
entries[139457] = { ["name"] = "Odyns Herausforderung", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Odyn persönlich lädt die mächtigsten Champions von Azeroth dazu ein, seine Hallen zu betreten und sich mit seinen Kriegern zu messen.\"" }
entries[139458] = { ["name"] = "Salbe gegen Teufelsfledermaustoxin", ["text"] = "Questgegenstand\n\"Wirkt dem Toxin entgegen, das bei Bissen von Teufelsfledermäusen zu Eiter und Fäulnis führt.\"" }
entries[139459] = { ["name"] = "Segen des Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Gewährt beim Einsatz 'Segen des Lichts'. Wenn Ihr tödlichen Schaden erleidet, lässt das Licht Euch mit voller Gesundheit zurückkehren und alle umgebenden Gegner zurückstoßen.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139460] = { ["name"] = "Siegel des verheerten Schicksals", ["text"] = "\"Verändert Euer Schicksal und gibt Euch die Möglichkeit, im Smaragdgrünen Alptraum oder in der Nachtfestung zusätzliche Schätze zu erhalten.\"" }
entries[139461] = { ["name"] = "Rune der Dunkelheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\nBenutzen: Aktiviert die Rune, um 'Umhüllung der Dunkelheit' zu erhalten. Wenn Ihr tödlichen Schaden erleidet, lässt die Dunkelheit Euch mit voller Gesundheit zurückkehren und alle umgebenden Gegner zurückstoßen.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139463] = { ["name"] = "Salbe gegen Teufelsfledermaustoxin", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verabreicht Eurem Ziel eine einzelne Dosis Gegengift für Teufelsfledermaustoxin. (4 Sek. Abklingzeit)\n\"Wirkt dem Toxin entgegen, das bei Bissen von Teufelsfledermäusen zu Eiter und Fäulnis führt.\"" }
entries[139464] = { ["name"] = "Linse der Gezeiten", ["text"] = "Questgegenstand\nEinzigartig\n\"Über ein nicht dokumentiertes Ritual können Bilder aus dem Verstand durch die Linse projiziert werden.\"" }
entries[139465] = { ["name"] = "Fläschchen Dämonenblut", ["text"] = "Questgegenstand\n\"Die Flüssigkeit blubbert und brodelt, als wäre sie lebendig.\"" }
entries[139466] = { ["name"] = "Bindungen des Windlords", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n\"Die linke Hälfte eines Gefängnisses, das für den Windlord Donneraan gedacht war.\"" }
entries[139467] = { ["name"] = "Beutetasche", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[139468] = { ["name"] = "Bindungen des Windlords", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n\"Die rechte Hälfte eines Gefängnisses, das für den Windlord Donneraan gedacht war.\"" }
entries[139469] = { ["name"] = "Essenz der Wildheit", ["text"] = "Questgegenstand" }
entries[139471] = { ["name"] = "Schreiben an die Rabenwehr", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Lord Rabenkrone, die Legion stimmt Euren Bedingungen zu. Die Verstärkung wird wie erwartet eintreffen. Vergesst nicht, Euren Teil des Pakts zu erfüllen.\"" }
entries[139472] = { ["name"] = "Einladung zu einer glamourösen Feier", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ihr seid herzlich auf das Juwelenverzierte Anwesen eingeladen, wo Euch ergötzliche Leckereien und Getränke und womöglich sogar ein Überraschungsgast erwarten...\"" }
entries[139473] = { ["name"] = "Phiole mit vergiftetem Blut", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Blut, das einer unglückseligen verderbten Kreatur im Finsterherzdickicht abgezapft wurde.\"" }
entries[139474] = { ["name"] = "Gravierte Muschelschale", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Wenn Ihr sie Euch ans Ohr haltet, hört Ihr eine bösartige Stimme in der Ferne.\"" }
entries[139475] = { ["name"] = "Durchnässter Brief", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Meine Liebste, ich fürchte, meine schlechten Taten haben mich nun endlich eingeholt. Mir steht eine Ewigkeit in der Unterwelt bevor, in der ich über das Meer segele und Helyas Gnade unterworfen bin. Vergiss mich nicht.\"" }
entries[139476] = { ["name"] = "Gesprungene Drachenschuppe", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Die Drogbar haben sie an einem besonderen Platz aufgehoben, als Erinnerung an die Macht, die Todesschwinge einst innewohnte.\"" }
entries[139477] = { ["name"] = "Ausgelaugte Manakugel", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Diese Kugel quoll einst vor Energie über, doch das Mana wurde nun vollständig aufgezehrt.\"" }
entries[139478] = { ["name"] = "Zerbrochener Wächterinnenhelm", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Dieser Helm gehörte einst einer stolzen Wächterin. Was wohl aus ihr geworden ist?\"" }
entries[139479] = { ["name"] = "Zerbrochener Portalsplitter", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein Bruchstück eines Portals der Legion.\"" }
