entries[139501] = { ["name"] = "Frostklippentrommeln", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schlagt die Trommeln, um Jorhuttam zu seinem Fütterungsbereich zu locken." }
entries[139502] = { ["name"] = "Zügel des Todesstreitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\nBenutzen: Beschwört ein Todesstreitross der Schwarzen Klinge, das im Kampf geritten werden kann, oder gibt es wieder frei.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
entries[139503] = { ["name"] = "Bluttotemsatteldecke", ["text"] = "Benutzen: Platziert eine Satteldecke auf Eurem Reittier, durch die das Reiten für 2 Stunden weitaus komfortabler wird.\n\nDie Dauer dieses Effekts ist für Schneider vervierfacht." }
entries[139505] = { ["name"] = "Zügel des Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\nBenutzen: Beschwört ein Streitross der Silbernen Hand, das im Kampf geritten werden kann, oder gibt es wieder frei.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:" }
