entries[139513] = { ["name"] = "Handschriftliche Einladung", ["text"] = "Wird beim Aufheben gebunden\n\"Mit schwach leuchtender Tinte verfasst. Das Pergament duftet dezent nach Blumen.\"\n<Zum Lesen rechtsklicken>" }
entries[139520] = { ["name"] = "Fieberhaftes Bittgebet", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Der Inhalt ist zwar nicht völlig unzusammenhängend, wurde jedoch eindeutig von jemandem mit hohem Fieber verfasst.\"" }
