entries[139534] = { ["name"] = "Blutiger Brief", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine Nachricht wurde hastig mit Blut auf einen Stofffetzen geschmiert.\"" }
entries[139535] = { ["name"] = "Blutiges Stoßgebet", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine Nachricht wurde hastig mit Blut auf einen Stofffetzen geschmiert.\"" }
entries[139536] = { ["name"] = "Emanation der Winde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nBenutzen: Schaltet die Artefaktvorlage \"Donnerzorn, Geweihte Klinge des Windfürsten\" für die Schreckensklingen frei.\n\"Geheimnisse elementarer Macht schlummern in der berühmten Klinge von Donneraan dem Windlord.\"" }
entries[139537] = { ["name"] = "Zopf des Unterkönigs", ["text"] = "Questgegenstand\n\"Dieser magische, schamanistische Zopf wurde seit den ersten Tagen von jedem der Unterkönige getragen.\"" }
entries[139538] = { ["name"] = "Alptraumpeitsche", ["text"] = "Questgegenstand\n\"Diese Peitsche wurde aus der dunklen Energie von Xavius selbst erschaffen.\"" }
entries[139539] = { ["name"] = "Uralte Wellenskornklinge", ["text"] = "Questgegenstand\n\"Die hoch angesehene Waffe eines längst verstorbenen Wellenskornkriegers.\"" }
entries[139540] = { ["name"] = "Seite aus Aponis Tagebuch", ["text"] = "Questgegenstand\n\"Hastig geschrieben.\"" }
entries[139541] = { ["name"] = "Siegel der Befehlsgewalt", ["text"] = "Questgegenstand\nBenutzen: Teleportiert zur Dämonenwelt Niskara. (3 Sek. Abklingzeit)\n\"Leuchtet in der Gegenwart eines Legionsportals.\"" }
entries[139542] = { ["name"] = "Streifen Segeltuch", ["text"] = "Wird beim Aufheben gebunden\n\"Vermutlich kann nicht einmal ein Schneider etwas damit anfangen.\"\nVerkaufspreis:" }
entries[139543] = { ["name"] = "Zerbrochene Pinne", ["text"] = "Wird beim Aufheben gebunden\n\"Ein talentierter Schiffsbauer könnte dies vielleicht weiterverwerten.\"\nVerkaufspreis:" }
entries[139544] = { ["name"] = "Verfallendes Kriegsbanner der Wellenskorn", ["text"] = "Wird beim Aufheben gebunden\n\"Wehte einst stolz an den Masten der Vrykullangschiffe.\"\nVerkaufspreis:" }
entries[139545] = { ["name"] = "Verrostete Schiffsglocke", ["text"] = "Wird beim Aufheben gebunden\n\"Wurde verwendet, um bei dichtem Nebel andere Schiffe zu warnen.\"\nVerkaufspreis:" }
entries[139546] = { ["name"] = "Verzerrendes Anima der Seelen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Todesritter\nBenutzen: Schaltet die Artefaktvorlage \"Berührung des Untodes\" für den Schlund der Verdammten frei.\n\"Ein fehlgeschlagenes Experiment, bei dem sich jemand auf magische Weise an der Macht der längst Verstorbenen bereichern wollte. Das Ergebnis zuckt und bebt noch immer auf beunruhigende Art und Weise.\"" }
entries[139547] = { ["name"] = "Runen der Verdunkelung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Todesritter\nBenutzen: Schaltet die Artefaktvorlage \"Dunkle Runenklinge\" für die Klingen des gefallenen Prinzen frei.\n\"Obwohl sie in einer uralten Sprache verfasst sind, an die sich heute keine lebende Seele mehr erinnert, scheinen Euch diese Worte wie auf die Zunge zu springen. So, als wollten sie, dass man sie ausspricht.\"" }
entries[139548] = { ["name"] = "Der Haken des Knochenernters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Todesritter\nBenutzen: Schaltet die Artefaktvorlage \"Knochenernter\" für Apokalypse frei.\n\"Diese primitive und brutale Waffe wurde durch die stetige Energieablagerung aus der Eiskronenzitadelle genährt und lässt sich ohne Weiteres in ein Werkzeug des Todes verwandeln.\"" }
entries[139549] = { ["name"] = "Tarnung des Todeswandlers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Dämonenjäger\nBenutzen: Schaltet die Artefaktvorlage \"Todeswandler\" für die Zwillingsklingen des Betrügers frei.\n\"Die dunkle Waffe eines längst verstorbenen Meisters. Auch heute dürstet sie noch nach Blut.\"" }
entries[139550] = { ["name"] = "Bollwerk des Eisernen Wächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Dämonenjäger\nBenutzen: Schaltet die Artefaktvorlage \"Eiserner Wächter\" für die Kriegsklingen der Aldrachi frei.\n\"Einst ein unbeugsames Konstrukt der Draenei, dann ein Werkzeug der Zerstörung in den Händen der Legion. Dieser Eiserne Wächter fiel vor langer Zeit bei der Invasion der Heimatwelt der Aldrachi.\"" }
entries[139551] = { ["name"] = "Die Sonnenblüte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Schaltet die Artefaktvorlage \"Hand des Sonnenhüters\" für die Sichel von Elune frei.\n\"Eine seltene Blume aus dem Smaragdgrünen Traum, die seit dem Krieg der Ahnen niemand mehr auf Azeroth gesehen hat.\"" }
entries[139552] = { ["name"] = "Feder des Mondgeistes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Schaltet die Artefaktvorlage \"Mondgeist\" für die Fänge von Ashamane frei.\n\"Eine einzelne Feder von einer wilden Gottheit, die nur wenige je zu Gesicht bekommen haben. Damit können Druiden der Klaue eine bisher nie gesehene Gestalt meistern.\"" }
entries[139553] = { ["name"] = "Mal des Lichtungswächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Schaltet die Artefaktvorlage \"Wächter der Lichtung\" für Ursocs Klauen frei.\n\"Mit diesem mächtigen Mal verleiht Ursol allen Bären große Kräfte, die in Zeiten der Not die Wildnis vor Gefahr schützen sollen.\"" }
entries[139554] = { ["name"] = "Eichel des Unendlichen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Schaltet die Artefaktvorlage \"Krone des Wächters\" für G'Hanir, den Mutterbaum frei.\n\"Diese magischen Eicheln stammen von einem der ältesten Bäume im Traum und konnten in Sicherheit gebracht werden, bevor er dem Alptraum anheimfiel.\"" }
entries[139555] = { ["name"] = "Entwürfe des großen Architekten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nBenutzen: Schaltet die Artefaktvorlage \"Arm der Titanen\" für Titanenblitz frei.\n\"Detaillierte Pläne für ein wahres Meisterwerk technomagischer Bogenbaukunst, dessen Kern eine mächtige, von Titanen geschmiedete Energiequelle birgt. Wie diese Pläne den Weg aus Mimirons Archiv gefunden haben, ist unbekannt.\"\nVerkaufspreis:" }
entries[139556] = { ["name"] = "Syriel Sichelsturz' Notizen: Rabenwächter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nBenutzen: Schaltet die Artefaktvorlage \"Rabenwächter\" für Thas'dorah, Erbstück von Haus Windläufer frei.\nBenötigt Farondis' Hofstaat\n- Respektvoll\n\"Ausführliche Pläne für die Herstellung einer eleganten und mächtigen Armbrust, die in der Zeit verschollen gingen, da die benötigten Materialien nicht existiert haben.\"\nVerkaufspreis:" }
entries[139557] = { ["name"] = "Letzter Atem des Waldes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nBenutzen: Schaltet die Artefaktvorlage \"Kraft der Bärenseele\" für Fangklaue, Speer der wilden Götter frei.\n\"Zweimal opferte Ursoc der Wildnis sein Leben. Aber er hinterließ ein Vermächtnis, für das andere noble Verteidiger in seiner Abwesenheit eintreten sollten.\"" }
entries[139558] = { ["name"] = "Die Bürde des Wollomanten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Schaltet die Artefaktvorlage \"Die Bürde des Wollomanten\" für Aluneth frei.\n\"Cote 'der Hirte' Metcalf konnte die Rätsel dieses geheimnisvollen blökenden Stabs nicht ergründen.\"" }
entries[139559] = { ["name"] = "Entwurf der Sterne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Schaltet die Artefaktvorlage \"Entwurf der Sterne\" für Felo'melorn frei.\n\"Ein Plan der Nachtgeborenen für eine Zauberklinge zu Ehren eines Sternbilds, das von ihrem Volk verehrt wird.\"" }
entries[139560] = { ["name"] = "Immerflammenkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Schaltet die Artefaktvorlage \"Frostfeuerangedenken\" für Schwarzfrost frei.\n\"Ein gefrorener Kristall, erleuchtet von einem ewigen Feuer, das keinerlei Wärme erzeugt. Ihr könnt ihn ruhig berühren, denn er sieht nicht aus, als würde er jemals schmelzen.\"" }
entries[139561] = { ["name"] = "Legende des Affenkönigs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\nBenutzen: Schaltet die Artefaktvorlage \"Uralter Bräuhüter\" für Fu Zan, Gefährte des Wanderers frei.\n\"Ein ziemlich starkes und besonderes Gebräu, das angeblich vom Affenkönig höchstpersönlich hergestellt wurde. Das Fass sieht kostbar aus und ließe sich vielleicht auch noch für etwas anderes einsetzen als die Lagerung von Gebrautem...\"" }
entries[139562] = { ["name"] = "Atem der unsterblichen Schlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\nBenutzen: Schaltet die Artefaktvorlage \"Atem der unsterblichen Schlange\" für Sheilun, Stab der Nebel frei.\n\"Ein wirbelnder Quell magischer Energie, der angeblich aus dem Bauch eines Großdrachen stammt, der älter ist als die Zeit selbst.\"" }
entries[139563] = { ["name"] = "Die Fäuste des Sturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\nBenutzen: Schaltet die Artefaktvorlage \"Fäuste des Sturms\" für die Fäuste der Himmel frei.\n\"Über die Entstehung der Sturmfaust ist nur wenig bekannt, aber die darin enthaltene Macht scheint sowohl von Therazane als auch von Al'Akir zu stammen – eine eher unerwartete Verbindung.\"" }
entries[139564] = { ["name"] = "Verlorene Edikte des Behüters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenutzen: Schaltet die Artefaktvorlage \"Waffen des Wächters\" für die Silberne Hand frei.\n\"Wir haben geschworen, dieser gepeinigten Welt die Hoffnung zurückzugeben, Tyrannei und Unrecht auszulöschen, wo immer wir sie antreffen, und den Hammer der Gerechtigkeit auf jene niederfahren zu lassen, die sich mit dem Bösen eingelassen haben.\"" }
entries[139565] = { ["name"] = "Funken des gefallenen Exarchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenutzen: Schaltet die Artefaktvorlage \"Bollwerk des Verteidigers\" für den Wahrheitshüter frei.\n\"Als Exarch Kelios fiel, schwand auch die letzte Hoffnung, den Tempel halten zu können. Die Legion hatte gesiegt. Nur ein Gedanke ließ sie jetzt noch Frieden finden: der Gedanke an alle, die entkommen waren. Aber auch das würde ihnen die Legion bald nehmen.\"" }
entries[139566] = { ["name"] = "Herz der Verderbnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenutzen: Schaltet die Artefaktvorlage \"Verderbtes Andenken\" für den Aschenbringer frei.\n\"Ein düsterer Einblick in eine Vergangenheit, die der Aschenbringer hinter sich ließ und von der viele hofften, dass sie niemals wiederaufleben würde.\"" }
entries[139567] = { ["name"] = "Schriftstücke des Endes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Schaltet die Artefaktvorlage \"Spitze des Foliantwächters\" für den Zorn des Lichts frei.\n\"Diese Worte, zusammengetragen aus den Folianten des Archivars, ergeben eine düstere Prophezeiung.\"" }
entries[139568] = { ["name"] = "Stab der Lichtgeborenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Schaltet die Artefaktvorlage \"Krone der Lichtgeborenen\" für T'uure, Fanal der Naaru frei.\n\"Die Macht der Valkyra lässt den Stab in sanften Tönen schwingen. Berührt man ihn, verstummt er jedoch.\"" }
entries[139569] = { ["name"] = "Klaue von N'Zoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Schaltet die Artefaktvorlage \"Klaue von N'Zoth\" für Xal'atath, Klinge des Schwarzen Imperiums frei.\n\"Blinzelnde Augen. Pulsierendes Fleisch. Es ist eindeutig am Leben.\"" }
entries[139570] = { ["name"] = "Die Chiffre des gebrochenen Knochens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nBenutzen: Schaltet die Artefaktvorlage \"Knochenbrecher\" für die Königsmörder frei.\n\"Die Geheimnisse einer längst verstorbenen Assassine, die alle nur 'Die Knochenbrecherin' nannten. Es heißt, sie hätte ihren Opfern stets die Beine gebrochen, nachdem eines von ihnen von den Toten zurückgekehrt war, um sich an ihr zu rächen.\"" }
entries[139571] = { ["name"] = "Foliant der außerweltlichen Gifte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nBenutzen: Schaltet die Artefaktvorlage \"Giftbiss\" für die Reißzähne des Verschlingers frei.\n\"Ein Text, der über viele Generationen von den Schattenjägern der Zandalari vererbt wurde. Er behandelt ausführlich die exotischen Waffen und Gifte, mit denen sie sich ihrer Feinde entledigten.\"" }
entries[139572] = { ["name"] = "Verlorener Kodex der Amani", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBenutzen: Schaltet die Artefaktvorlage \"Stolz der Amani\" für die Faust des Ra-den frei.\n\"Ein lange verlorener Trolltext über den Aufstieg und Fall der Anführer vieler Generationen. Ein großer Teil ist einem Troll namens Atai'natha und der mächtigen magischen Klaue gewidmet, mit der er seinen Befehlen Nachdruck verlieh.\"" }
entries[139573] = { ["name"] = "Der Kriegskolben von Shirvallah", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBenutzen: Schaltet die Artefaktvorlage \"Champion der Zandalari\" für den Schicksalshammer frei.\n\"Trotz seiner zierreichen Konstruktion hat dieser brutale Streitkolben viele das Leben gekostet – und das alles zu Ehren der wilden Gottheit Shirvallah. Vor langer Zeit ging die Waffe im Meer verloren, gemeinsam mit dem Hohepriester, der sie einst trug.\"" }
entries[139574] = { ["name"] = "Spule der ertränkten Königin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBenutzen: Schaltet die Artefaktvorlage \"Schlangenschlinge\" für Sharas'dal, Szepter der Gezeiten frei.\n\"Nun, da sie sich wie Schlangen unter den Wellen wanden, hatten die Hochgeborenen nichts mehr mit ihrer einstigen Gestalt gemein. Sie waren nun eins mit der Tiefe und dienten etwas Finsterem, das dort lauerte...\"" }
entries[139575] = { ["name"] = "Essenz des Scharfrichters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Schaltet die Artefaktvorlage \"Des Schicksals Ende\" für Ulthalesh, Sense der Totenwinde frei.\n\"Diese aus den Schädeln von großen Champions destillierte Essenz verspricht große Macht – sofern man bereit ist, den finsteren Preis zu bezahlen.\"" }
entries[139576] = { ["name"] = "Gesicht des ersten Erweckers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Schaltet die Artefaktvorlage \"Thal'kiels Fratze\" für den Schädel der Man'ari frei.\n\"Zu den bekanntesten Phrenologen dieser Zeit gehörten Thal'kiel und Archimonde. Besonders Thal'kiel war für seinen markanten Schädel bekannt – den Inbegriff eines Zaubererhauptes.\"" }
entries[139577] = { ["name"] = "Das brennende Juwel des Sargeras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Schaltet die Artefaktvorlage \"Legionsschrecken\" für das Szepter des Sargeras frei.\n\"Ein dunkles Feuer brennt in den Tiefen dieses blutroten Juwels. Gierig züngeln die Flammen an seinen Kanten empor, als Ihr Euch nähert.\"" }
entries[139578] = { ["name"] = "Arkanitklingenbrecher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nBenutzen: Schaltet die Artefaktvorlage \"Arkanitklingenbrecher\" für Strom'kar den Kriegsbrecher frei.\n\"Echte Handarbeit von Helgar, dem Meisterschmied der Himmelsfeste. Diese Axt ist wohl mächtiger als jede auf Azeroth hergestellte stählerne Klinge.\"" }
entries[139579] = { ["name"] = "Die Drachenschlächter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nBenutzen: Schaltet die Artefaktvorlage \"Schneide des Drachentöters\" für die Kriegsschwerter der Valarjar frei.\n\"Zwei furchteinflößende Äxte – hergestellt aus von den Vrykul verzaubertem Runenholz und gekrönt mit den Schädeln erschlagener Großdrachen. Beim Anblick dieser Waffen jubelt das Kriegerherz.\"" }
entries[139580] = { ["name"] = "Brennende Plattenrüstung des Weltenbrechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nBenutzen: Schaltet die Artefaktvorlage \"Letzter Atem des Weltenbrechers\" für die Schuppe des Erdwächters frei.\n\"In den Rillen fließt dunkles geschmolzenes Blut von Neltharion höchstpersönlich, das seit unzähligen Jahren in seinem einstigen Hort schwelt und darauf wartet, endlich wieder mit einer Schuppe der gleichen Herkunft vereint zu werden.\"" }
entries[139583] = { ["name"] = "Dämonische Rune", ["text"] = "Questgegenstand\n\"Auf dem Stein sind unverständliche Zeichen eingraviert.\"" }
entries[139584] = { ["name"] = "Haftbomben", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft Eurem Ziel eine Haftbombe entgegen, die nach 5 Sek. detoniert und allen Gegnern innerhalb von 5 Metern (375% der Angriffskraft) Schaden zufügt.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden. (30 Sek. Abklingzeit)\n15 Aufladungen" }
entries[139585] = { ["name"] = "Rauchpulver", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft das Rauchpulver auf den Boden und verbirgt Euch in einem Rauch, der Euch verschwinden lässt.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\n10 Aufladungen" }
entries[139586] = { ["name"] = "Disteltee", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt 100 Energie wieder her.\n\nKann nur auf den Verheerten Inseln genutzt werden. (5 Sek. Abklingzeit)\n10 Aufladungen" }
