entries[139652] = { ["name"] = "Leyschimmerkrötenfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Besonders scheu und schwer zu fangen.\"\nVerkaufspreis:" }
entries[139653] = { ["name"] = "Nar'thalassischer Einsiedler", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Diese Krabbe verbirgt sich tagsüber im Sand der Flüsse und Lagunen von Azsuna.\"\nVerkaufspreis:" }
entries[139654] = { ["name"] = "Geisterhafter Königinnenfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Ein Geist des Königinnenfisches, wie er vor zehntausend Jahren aussah.\"\nVerkaufspreis:" }
entries[139655] = { ["name"] = "Schreckensfinne", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Eine Perversion des Alptraums, der Val'sharah heimgesucht hat.\"\nVerkaufspreis:" }
entries[139656] = { ["name"] = "Dornenflunder", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Von den Kiemen bis zur Flosse mit Stacheln übersäht.\"\nVerkaufspreis:" }
entries[139657] = { ["name"] = "Uralte Mooskieme", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"In den mondbeschienenen Gewässern von Val'sharah gedeihen die Mooskiemen besonders gut.\"\nVerkaufspreis:" }
entries[139658] = { ["name"] = "Bergkugelfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Sie werden von den Murlocs am Hochberg verehrt.\"\nVerkaufspreis:" }
entries[139659] = { ["name"] = "Kaltwasserkarpfen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Diese Spezies hasst warmes Wasser und bevorzugt die eisigen Gewässer des schneereichen Hochbergs.\"\nVerkaufspreis:" }
entries[139660] = { ["name"] = "Uralter Hochberglachs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Da die Drogbar gnadenlos Jagd auf Hochberglachse machen, werden sie selten so alt.\"\nVerkaufspreis:" }
entries[139661] = { ["name"] = "Oodelfjisk", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Der Oodelfjisk ist vor langer Zeit durch Überfischung ausgerottet worden.\"\nVerkaufspreis:" }
entries[139662] = { ["name"] = "Graubauchhummer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Wird von allem angelockt, was glänzt.\"\nVerkaufspreis:" }
entries[139663] = { ["name"] = "Donnernder Sturmrochen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Die größten Sturmrochen sind auch am tödlichsten.\"\nVerkaufspreis:" }
entries[139664] = { ["name"] = "Magieschluckerfrosch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Wie auch die Nachtgeborenen haben die Frösche Suramars einen unstillbaren Appetit auf Magie entwickelt.\"\nVerkaufspreis:" }
entries[139665] = { ["name"] = "Sehergratkugelfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Bei einigen Gelegenheiten wurden Murlocs dabei entdeckt, wie sie diese Fische als Waffen einsetzten.\"\nVerkaufspreis:" }
entries[139666] = { ["name"] = "Besudelter Runenschuppenkoi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Die Schuppen eines Fisches, doch das Herz eines Dämons. Nicht einmal die Fische sind sicher vor der Legion.\"\nVerkaufspreis:" }
entries[139667] = { ["name"] = "Axtfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Ähnlich einem Schwertfisch, aber mit geringerem Angriffstempo.\"\nVerkaufspreis:" }
entries[139668] = { ["name"] = "Seebodenkalmar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Nicht angelbar, da diese Tiere hunderte Meter tief unter der Meeresoberfläche leben. Diese Kalmare müssen mit... alternativen Methoden gefischt werden.\"\nVerkaufspreis:" }
entries[139669] = { ["name"] = "Uralter schwarzer Barrakuda", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Fisch zurück ins Wasser und gewährt Eurem Angelartefakt 50 Artefaktmacht.\n\"Vom berühmt-berüchtigten Walhai abgesehen, ist dies einer der größten Fische in den Meeren Azeroths.\"\nVerkaufspreis:" }
entries[139670] = { ["name"] = "Schrei der Toten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Beschwört einen Trupp von Aspiranten der Valarjar, die Eure Champions auf Missionen begleiten." }
entries[139671] = { ["name"] = "Todesblickiris", ["text"] = "Questgegenstand\n\"Sie... starrt Euch direkt an...\"" }
entries[139672] = { ["name"] = "Horn des Alptraumfürsten", ["text"] = "Questgegenstand\n\"Eine Berührung erfüllt Euch mit intensivem Zorn und Hass.\"" }
entries[139673] = { ["name"] = "Brustschutz des Todesgebieters", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 7.\nHaltbarkeit 140 / 140\nKlassen: Todesritter\nSchließt Eure Ordenskampagne ab.\n\nKampfplatte des Todesgebieters (0/8)\nBrustschutz des Todesgebieters\nGroßstiefel des Todesgebieters\nStulpen des Todesgebieters\nHelm des Todesgebieters\nBeinschützer des Todesgebieters\nMantel des Todesgebieters\nGurt des Todesgebieters\nArmschienen des Todesgebieters\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Erhöht in Außengebieten der Verheerten Inseln Eure Regeneration außerhalb des Kampfes.\n(4) Set : Wenn Eure Gesundheit unter 35% liegt, erleidet Ihr in Außengebieten der Verheerten Inseln 50% weniger Schaden.\n(6) Set : Erhöht die Stärke um 18 .\n(8) Set : Beim Aufzehren einer Rune besteht eine Chance, dass Eure Meisterschaft 12 Sek. lang um 71 erhöht wird.\nVerkaufspreis:" }
