entries[139771] = { ["name"] = "Brodelnde Essenz", ["text"] = "Wird beim Aufheben gebunden\n\"Eine schreckliche Masse an verderbter Essenz, die von unsteter Energie zusammengehalten wird.\"\n<Zum Öffnen rechtsklicken>" }
entries[139772] = { ["name"] = "Natalies Tagebuch", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Sammlung Notizen, die von der Anführerin des Kults der Vergessenen Schatten verfasst wurden.\"" }
entries[139773] = { ["name"] = "Smaragdwinde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Drückt Euch vom Boden ab und reitet auf einer Windböe. Kann nur auf den Verheerten Inseln verwendet werden. (10 Min Abklingzeit)\n\"Der Wind von Val'sharah weht über die Verheerten Inseln und bringt die Saat und den Duft der Wildnis mit sich.\"\nVerkaufspreis:" }
entries[139775] = { ["name"] = "Enthusiast der Allianz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren frohen Spielmann beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Ehrestufe 20.\nVerkaufspreis:" }
