entries[139780] = { ["name"] = "Schriftrolle von Elun'dris", ["text"] = "Questgegenstand\nBenötigt Die Nachtsüchtigen\n- Respektvoll\n\"Eine verbotene Abhandlung über das Herz von Zin-Azshari und seine Rolle für die Herrschaft der Königin über die große Stadt.\"\nVerkaufspreis:" }
entries[139781] = { ["name"] = "Marin Noggenfoggers Glücksmünze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Marin Noggenfogger will das sicherlich zurückhaben.\"" }
entries[139782] = { ["name"] = "Zauberschutze, Siegel und die Lebensart der Nachtgeborenen", ["text"] = "Questgegenstand\n\"Erstauflage.\"" }
entries[139783] = { ["name"] = "Verwittertes Relikt", ["text"] = "Einzigartig\n\"Sieht einem Schädel ähnlich, doch die wichtigen Merkmale haben sich über die Jahre abgenutzt.\"\nVerkaufspreis:" }
entries[139785] = { ["name"] = "Geschichten von den Verheerten Inseln", ["text"] = "\"Kann bei Dazzik 'Prachtmeer' auf der Schattenseite von Dalaran abgegeben oder bei einem Händler für Gold verkauft werden.\"\nVerkaufspreis:" }
