entries[140027] = { ["name"] = "Leyfunke", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Eure Angriffe haben eine Chance, Euch 15 Sek. lang alle 0.5 Sek. 1 Beweglichkeit zu gewähren. (15s Abklingzeit)\nVerkaufspreis:" }
entries[140030] = { ["name"] = "Teufelssaurierschockstab", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, 43 Naturschaden zu verursachen und das Ziel für 6 Sek. um 50% zu verlangsamen.\nVerkaufspreis:" }
entries[140031] = { ["name"] = "Manafunke", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Zauber haben eine Chance, Euch für 20 Sek. 'Überladen' zu gewähren und Eure Intelligenz um 4 zu erhöhen. (20s Abklingzeit)\nVerkaufspreis:" }
entries[140034] = { ["name"] = "Einschlagsbeben", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Eure Angriffe haben eine Chance, 'Teufelssaurierstampede' zu aktivieren, wodurch Eure Schritte Gegnern in der Nähe im Verlauf von 8 Sek. [Quellwert] körperlichen Schaden zufügen.\n\"Könnt Ihr nicht schneller rennen?\"\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[140035] = { ["name"] = "Fluktuierender Bogenkondensator", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Angriffe haben eine Chance, Eure Stärke für 20 Sek. um 3 , 4 oder 5 zu erhöhen. (20s Abklingzeit)\n\"Kann 1,21 Manafunken verarbeiten.\"\nVerkaufspreis:" }
entries[140037] = { ["name"] = "Technik: Ungeschriebene Legende", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine ungeschriebenen Legende herstellt.\nStellt eine ungeschriebene Legende her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nUngeschriebene Legende\nBenutzen: Beginnt, Eure Legende zu schreiben. Das Töten von Gegnern bis Stufe 49 fügt dem Buch ebenfalls eine Zeile hinzu. Spielercharaktere, die in Inschriftenkunde bewandert sind, schreiben ihr Buch viermal so schnell.\n\nWenn das Buch vollständig ist, kann es an Händler verkauft oder in Dalarans Schattenseite gegen blinde Augen eingetauscht werden.\nVerkaufspreis:\nBenötigt Leichtes Pergament (50), Fahle Pigmente (24), Rosenrote Pigmente (50)" }
