entries[140090] = { ["name"] = "Was kam zuerst - Samenkorn oder Baum?", ["text"] = "Questgegenstand\nEinzigartig\n\"Gedanken zum Ursprung des Lebens auf Azeroth von Erzdruide Vorenthias.\"" }
entries[140091] = { ["name"] = "Die Geheimnisse der wilden Götter", ["text"] = "Questgegenstand\nEinzigartig\n\"Berichte zu den zahlreichen wilden Göttern Azeroths und deren Sichtungen im Laufe von Tausenden Jahren Geschichte.\"" }
entries[140092] = { ["name"] = "Druiden des Rudels", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine mahnende Geschichte über Stolz, Hochmut und die zahlreichen Gefahren des Gestaltwandels.\"" }
entries[140093] = { ["name"] = "Die unbekannten Geschichten aus dem Krieg der Ahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger , Druide\n\"Eine genauere Betrachtung der weniger bekannten Ereignisse aus dem Krieg der Ahnen und ihres Einflusses auf die Zukunft Azeroths.\"" }
entries[140094] = { ["name"] = "Von uralter Magie und ihrer Anwendung, ohne die Welt zu zerstören", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Sammlung des Wissens vieler großer Erzmagier der Kirin Tor. Enthält genaue Beschreibungen der Torheiten, die fahrlässige Magier vergangener Zeiten begangen haben.\"" }
entries[140095] = { ["name"] = "Von Seuchen, Flüchen und der Pest", ["text"] = "Questgegenstand\nEinzigartig\n\"Düstere Geschichten über zahlreiche tragische Ereignisse auf Azeroth und die Mächte, die dafür verantwortlich waren. Festgehalten von der königlichen Historikerin Archesonus.\"" }
entries[140096] = { ["name"] = "Der Teufelsfoliant von Vorgalus Dor", ["text"] = "Questgegenstand\nEinzigartig\n\"Dämonische Aufzeichnungen des verstorbenen Hexenmeisters Vorgalus Dor, die Berichte über viele uralte und mächtige Waffen aus fernen Welten der Legion enthalten.\"" }
entries[140097] = { ["name"] = "Der Untergang Lordaerons und der östlichen Lande", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Todesritter\n\"Geschichtliche Darstellungen der letzten Tage des Menschenkönigreichs Lordaeron. Festgehalten von der königlichen Historikerin Archesonus.\"" }
entries[140098] = { ["name"] = "Die Letzten der Illidari", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Abhandlung über Illidans Niederlage am Schwarzen Tempel sowie Spekulation über die Schicksale der vermissten Dämonenjäger, die von ihm ausgebildet wurden.\"" }
entries[140099] = { ["name"] = "Der Kodex der Toten", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Text der Nathrezim, der für die sterblichen Völker Azeroths kaum zu entziffern ist.\"" }
entries[140100] = { ["name"] = "Der Teufelsfoliant von Vorgalus Dor", ["text"] = "Questgegenstand\nEinzigartig\n\"Dämonische Aufzeichnungen des verstorbenen Hexenmeisters Vorgalus Dor, die Berichte über viele uralte und mächtige Waffen aus fernen Welten der Legion enthalten.\"" }
entries[140101] = { ["name"] = "Eine theoretische Untersuchung zu den Schwächen der Legion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister , Dämonenjäger\n\"Autor und Ursprungswelt dieses Werks sind unbekannt, doch die Legion wird es sicherlich verbrennen, wo immer sie es findet.\"" }
entries[140102] = { ["name"] = "Die Allianzexpedition nach Draenor", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Geschichte des kleinen Trupps aus Helden der Allianz, die sich durch das Dunkle Portal wagten, und von denen viele nie zurückkehrten.\"" }
entries[140103] = { ["name"] = "Die Geheimnisse der wilden Götter", ["text"] = "Questgegenstand\nEinzigartig\n\"Berichte zu den zahlreichen wilden Göttern Azeroths und deren Sichtungen im Laufe von Tausenden Jahren Geschichte.\"" }
entries[140104] = { ["name"] = "Der falsche Hüter", ["text"] = "Questgegenstand\nEinzigartig\n\"Recherchierte geschichtliche Berichte über die Ereignisse um Lokens Verrat an den restlichen Hütern. Verfasst von Historiker Llore.\"" }
entries[140105] = { ["name"] = "Die unbekannten Geschichten aus dem Krieg der Ahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n\"Eine genauere Betrachtung der weniger bekannten Ereignisse aus dem Krieg der Ahnen und ihres Einflusses auf die Zukunft Azeroths.\"\nVerkaufspreis:" }
entries[140106] = { ["name"] = "Das Opfer von Kaiser Shaohao", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Geschichte des großen Opfers, das Kaiser Shaohao erbrachte, sowie der folgenden herrscherlosen Generationen.\"" }
entries[140107] = { ["name"] = "Der Kodex der Toten", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Text der Nathrezim, der für die sterblichen Völker Azeroths kaum zu entziffern ist.\"" }
entries[140108] = { ["name"] = "Jenseits des Throns der Luft", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Geschichte über die Herrschaft der Luftelementare, die Zeit ihrer Verbannung und den ewigen Konflikt zwischen den Elementarlords.\"" }
entries[140109] = { ["name"] = "Meditation inmitten eines Hurrikans", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\n\"Eine Anleitung für die Kunst, sich selbst inmitten größten Tumults mit Frieden zu umgeben. Verfasst von Meister Xunsu.\"" }
entries[140110] = { ["name"] = "Liber Monasterii", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine heilige Schrift, von der insgesamt nur zwölf Exemplare geschaffen wurden. Von vielen davon nimmt man mittlerweile an, dass sie zerstört wurden.\"" }
entries[140111] = { ["name"] = "Der Krieg der Winterskorn", ["text"] = "Questgegenstand\nEinzigartig\n\"Übersetzungen mehrerer Texte auf irdenen Tafeln, die einen Vrykulkrieg in grauer Vorzeit beschreiben.\"" }
entries[140112] = { ["name"] = "Das Zeitalter des Galakrond", ["text"] = "Questgegenstand\nEinzigartig\n\"Interessante Erzählungen der Historikerin Evelyna über die ersten Drachen, die Hüter von Ulduar und die Ermächtigung der fünf Drachenaspekte.\"" }
entries[140113] = { ["name"] = "Legenden der Silbernen Hand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n\"Historisch fundierte und von Historikerin Evelyna nacherzählte Legenden über den vermuteten Ursprung der Paladine und ihr Verhältnis zum Licht, die bis an die Wurzeln der Menschheit zurückreichen.\"" }
entries[140114] = { ["name"] = "Berührung des Abgrunds", ["text"] = "Questgegenstand\nEinzigartig\n\"Verbotene Lehren darüber, wie man die Mächte der Leere anzapft und die ihnen innewohnenden Gefahren zu Waffen macht. Verfasst von Natalie Seline.\"" }
entries[140115] = { ["name"] = "Die Verderbnis der Eredar und die Flucht der Draenei", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein uralter Text, den die Draenei mit nach Azeroth gebracht hatten, der aber in den ersten Monaten außerhalb der Exodar verloren ging.\"" }
entries[140116] = { ["name"] = "Modguds Untergang", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine düstere Geschichte über eine Dunkeleisenzauberin, die ein Werkzeug der Alten Götter erlangte und unweigerlich seiner Verderbnis erlag.\"" }
entries[140117] = { ["name"] = "Die Jagd nach dem Zorn des Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n\"Ein Sammelwerk der Kirin Tor von Dalaran. Es warnt vor den Gefahren mächtiger instabiler Waffen, selbst in den Händen erfahrener Magier.\"" }
entries[140118] = { ["name"] = "Der Tag, an dem die Horde kam", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein persönlicher Bericht über die ersten Konflikte zwischen Menschen und Orcs. Verfasst von einem Berater König Llanes von Sturmwind.\"" }
entries[140119] = { ["name"] = "Der Kodex der Toten", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Text der Nathrezim, der für die sterblichen Völker Azeroths kaum zu entziffern ist.\"" }
entries[140120] = { ["name"] = "Der Teufelsfoliant von Vorgalus Dor", ["text"] = "Questgegenstand\nEinzigartig\n\"Dämonische Aufzeichnungen des verstorbenen Hexenmeisters Vorgalus Dor, die Berichte über viele uralte und mächtige Waffen aus fernen Welten der Legion enthalten.\"" }
entries[140121] = { ["name"] = "Die sieben Flüche der Südlichen Meere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n\"Alte Tavernengeschichten über das Unglück von sieben Piratenkapitänen und ihre noch nicht gefundenen Schätze.\"" }
entries[140122] = { ["name"] = "Die Verbannung der Elementarlords", ["text"] = "Questgegenstand\nEinzigartig\n\"Übersetzungen der uralten Erzählungen über die Verbannung der Elementarlords aus Azeroth. Verfasst von Historiker Llore.\"" }
entries[140123] = { ["name"] = "Das Lied der Schuppen", ["text"] = "Questgegenstand\nEinzigartig\n\"Behandelt die Ursprünge der Naga. Der Autor ist unbekannt.\"" }
entries[140124] = { ["name"] = "Jenseits des Throns der Luft", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Geschichte über die Herrschaft der Luftelementare, die Zeit ihrer Verbannung und den ewigen Konflikt zwischen den Elementarlords.\"" }
entries[140125] = { ["name"] = "Der Fall des Kriegshäuptlings", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n\"Gesammelte historische Darstellungen des Tods von Orgrim Schicksalshammer, erfasst von vielen der Kämpfer an seiner Seite.\"" }
entries[140126] = { ["name"] = "Von uralter Magie und ihrer Anwendung, ohne die Welt zu zerstören", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Sammlung des Wissens vieler großer Erzmagier der Kirin Tor. Enthält genaue Beschreibungen der Torheiten, die fahrlässige Magier vergangener Zeiten begangen haben.\"" }
entries[140127] = { ["name"] = "Das Schicksal von Aegwynn", ["text"] = "Questgegenstand\nEinzigartig\n\"Der letzte Teil der Aufzeichnungen über den Lebenswandel von Erzmagierin Aegwynn, Wächterin von Tirisfal. Verfasst vom Historiker Llore.\"" }
entries[140128] = { ["name"] = "Der Teufelsfoliant von Vorgalus Dor", ["text"] = "Questgegenstand\nEinzigartig\n\"Dämonische Aufzeichnungen des verstorbenen Hexenmeisters Vorgalus Dor, die Berichte über viele uralte und mächtige Waffen aus fernen Welten der Legion enthalten.\"" }
