entries[140130] = { ["name"] = "Die Stammeskriege und der Aufstieg Arathors", ["text"] = "Questgegenstand\nEinzigartig\n\"Erzählungen über das erste Königreich der Menschen. Recherchiert und verfasst von Historikerin Evelyna.\"" }
